-- «Batafsil» matnlari — Anbar Otin, Abdulla Oripov, Halima Xudoyberdiyeva
-- va Ozod Sharafiddinov.

-- ================================= ANBAR OTIN =================================

UPDATE fact_cards SET detail_uz = $$1870-yilda Qo'qonda tug'ilganman; to'liq ismim — Anbar Otin Farmonqul qizi.

Qo'qon o'sha davrda Farg'ona vodiysining eng yirik shahri va adabiy markazi edi. Mendan oldin bu yerda Uvaysiy va Nodira ijod qilgan. Men shu an'ananing davomchisiman. Tug'ilganimda Qo'qon xonligi allaqachon Rossiya imperiyasi tarkibiga kirgan edi va o'lka og'ir sharoitda yashardi — bu mening she'rlarimda aks etgan.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Otam shoira Uvaysiy izdoshlaridan edi, onam Ashurbibi esa hunarmand qizi bo'lgan.

Oilamizda she'riyatga muhabbat kuchli edi: otam mumtoz shoirlarning devonlarini o'qib berardi. Aynan shu muhit menda ijodga qiziqish uyg'otgan. Ammo oilamiz badavlat emasdi va men mehnat qilib kun ko'rganman. Kambag'allikni o'z tajribamdan bilganim she'rlarimning ijtimoiy yo'nalishini belgilagan.$$
 WHERE topic_uz = $$Oilam$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Dilshod otin maktabida tahsil olganman.

Dilshod otin — Qo'qonlik mashhur shoira va o'qituvchi; u o'z uyida qizlar uchun maktab ochgan va o'nlab yillar davomida saboq bergan. O'sha davrda qizlar uchun rasmiy maktab yo'q edi va bilim aynan shunday uy maktablarida — otinlar orqali berilardi. Bunday maktablar ayollar orasida savodxonlikni saqlab qolgan.$$
 WHERE topic_uz = $$O'qishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$She'r yozish bilan birga mahallamdagi qizlarga saboq berganim uchun «otin» deb atalganman.

«Otin» yoki «otin oyi» — qizlarga ta'lim beruvchi ayol o'qituvchi. Bu nom kasbni bildirardi va hurmat ma'nosiga ega edi. Otinlar qizlarga savod, she'riyat, axloq va uy yumushlarini o'rgatardi. Ustozim Dilshod otin ham, men ham shu ishni qilganmiz — bilimni keyingi avlodga uzatish an'anasi shu tariqa davom etgan.$$
 WHERE topic_uz = $$«Otin» nomim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$O'zbek va tojik tillarida ijod qilganman.

Qo'qon va butun Farg'ona vodiysida bu ikki til yonma-yon yashardi va ko'p oilada ikkalasi ham ishlatilardi. Shoir uchun ikki tilda yozish imkoniyatni kengaytiradi: har tilning o'z ohangi va so'z boyligi bor. Ikki tilli ijod bizning adabiyotimizda uzoq an'anaga ega — Navoiy ham turkiy va forsiy tillarda yozgan.$$
 WHERE topic_uz = $$Tillarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$1905-yilda o'zbekcha she'rlarimdan devon tuzganman.

Devonga g'azal, muxammas va boshqa janrlardagi she'rlarim kirgan. Devon tuzish shoir uchun muhim bosqich: u yozganlarini saralaydi va tartibga soladi. Men buni umrimning oxirgi yilida qilganman — go'yo o'z ijodimga yakun yasagandek. Devon qo'lyozma holida saqlanib qolgan va keyinchalik o'rganilgan.$$
 WHERE topic_uz = $$Devonim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$She'rlarimning aksariyati ijtimoiy mavzuda: adolatsizlik va mehnatkash odamlarning ahvoli haqida.

Bu mendan oldingi shoiralardan farqli jihat: Nodira va Uvaysiy asosan ishq va falsafiy mavzularda yozgan. Men esa atrofimda ko'rgan hayotni — kambag'allik, mehnat, ayollarning og'ir ahvolini yozganman. Buning sababi oddiy: men saroyda emas, oddiy mahallada yashaganman va shu hayotni bilardim.$$
 WHERE topic_uz = $$She'rlarim mavzusi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$She'rlarimda ilm va ma'rifatni ulug'laganman.

Men bilimni odamning ahvolini o'zgartira oladigan yagona kuch deb bilganman — ayniqsa qizlar uchun. O'zim o'qituvchi bo'lganim uchun bu masala menga yaqin edi: har kuni sinfimda o'tirgan qizlarning kelajagi ta'limga bog'liqligini ko'rib turardim. Bu qarash keyinchalik jadidlar harakatining ham asosiy g'oyasi bo'lgan.$$
 WHERE topic_uz = $$Ilm-ma'rifat$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$«Qarolar falsafasi» asarimda ayollarning va oddiy mehnatkash odamlarning og'ir ahvoli haqida yozganman.

«Qarolar» bu yerda kambag'al, mehnati bilan kun ko'radigan odamlarni bildiradi. Asar nasriy shaklda yozilgan va unda jamiyatdagi tengsizlik ochiq tanqid qilingan. Ayol muallifning bunday mavzuda yozishi o'sha davr uchun jasorat edi. Asar mening ijodimdagi eng jiddiy ishlardan biri sanaladi.$$
 WHERE topic_uz = $$«Qarolar falsafasi»$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$1906-yilda Qo'qonda vafot etganman — o'shanda men atigi o'ttiz olti yoshda edim.

Umrim qisqa bo'ldi, ammo ortimda devon, nasriy asar va o'nlab shogird qoldi. She'rlarim qo'lyozma holida saqlanib, keyingi avlodlarga yetib kelgan. Mustaqillik yillarida ijodim o'rganilib, she'rlarim nashr etilgan. Qisqa umr ko'rgan shoirning merosi ba'zan uzoq yashaydi.$$
 WHERE topic_uz = $$Umrimning oxiri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Qo'qonlik mashhur shoira Dilshod otinning maktabida o'qiganman.

U uzoq umr ko'rgan va o'nlab yillar davomida qizlarga saboq bergan; shuningdek u o'z zamondoshlari haqida yozib qoldirgan — bugun Uvaysiy va boshqa shoiralar haqidagi ba'zi ma'lumotlar aynan uning yozuvlaridan olingan. Ustozim menga she'riyat qoidalarini, aruz vaznini va mumtoz shoirlar ijodini o'rgatgan.$$
 WHERE topic_uz = $$Ustozim Dilshod otin$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Alisher Navoiy, Fuzuliy, Bedil, Uvaysiy va Nodira asarlarini sevib o'qiganman.

