 WHERE topic_uz = $$Sevimli shoirlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Men Uvaysiy va Nodira boshlagan o'zbek shoiralari an'anasini davom ettirganman.

Bu an'ananing o'ziga xosligi shundaki, u ustoz-shogird zanjiri orqali uzatilgan: Uvaysiy Nodiraga saboq bergan, Dilshod otin ularning izidan borgan, men esa Dilshod otindan o'qiganman. Shu tariqa ayollar ijodi uzluksiz davom etgan. Keyinchalik bu zanjir XX asr shoiralari — Zulfiya va boshqalarga ulangan.$$
 WHERE topic_uz = $$Shoiralar an'anasi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Men yashagan Qo'qon o'sha davrda yirik adabiy markaz edi.

Shaharda shoirlar davrasi, madrasalar va kutubxonalar bor edi; she'riy majlislar o'tkazilardi. Muqimiy va Furqat kabi shoirlar shu muhitda ijod qilgan — ular ham ijtimoiy mavzularda yozgan va ma'rifatni targ'ib qilgan. Bunday muhitda yashash shoir uchun muhim: atrofda o'qiydigan va bahslashadigan odamlar bo'lsa, ijod o'sadi.$$
 WHERE topic_uz = $$Qo'qon adabiy muhiti$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Otam Farmonqul asli marg'ilonlik bo'lgan, keyinchalik Qo'qonga ko'chib kelgan.

Marg'ilon — ipakchilik va hunarmandchilik shahri; u Qo'qondan uzoq emas. O'sha davrda odamlar ish va turmush sharoitiga qarab shaharlar orasida ko'chib yurardi. Otamning Qo'qonga kelishi mening taqdirimni belgilagan: agar u Marg'ilonda qolganida, men boshqa muhitda o'sardim va ijodim ham boshqacha bo'lardi.$$
 WHERE topic_uz = $$Otamning ona yurti$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$She'rlarimni o'z ismim — «Anbar» taxallusi bilan yozganman.

«Anbar» — xushbo'y modda nomi; u Sharq she'riyatida go'zallik va nafislik ramzi sifatida ishlatiladi. Ko'p shoir o'ziga alohida taxallus tanlagan, men esa o'z ismimni qoldirganman. Bu ham bir tanlov: shoir o'zini yashirmaydi, aksincha, aytgan gapiga o'z nomi bilan javob beradi.$$
 WHERE topic_uz = $$Taxallusim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

UPDATE fact_cards SET detail_uz = $$Qo'lyozmalarim bizgacha yetib kelgan va she'rlarim O'zbekistonda kitob holida nashr etilgan.

Qo'lyozmalar kutubxonalarda saqlanadi; ular ustida matnshunos olimlar ishlagan — matnni o'qish, izohlash va nashrga tayyorlash katta mehnat talab qiladi. Mustaqillik yillarida ijodim qayta o'rganilgan va she'rlarim adabiyot darsliklariga kiritilgan. Qo'qonda nomim bilan atalgan ko'chalar bor.$$
 WHERE topic_uz = $$She'rlarimning bugungi taqdiri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'anbar-otin');

-- =============================== ABDULLA ORIPOV ===============================

UPDATE fact_cards SET detail_uz = $$1941-yilda Qashqadaryo viloyati Koson tumanidagi Neko'z qishlog'ida tug'ilganman.

Tug'ilgan yilim urush boshlangan yil edi va bolaligim og'ir davrga to'g'ri keldi. Qishloq hayoti, dala mehnati va oddiy odamlarning turmushi — bularning barchasi keyinchalik she'rlarimga kirgan. Vatan mavzusi mening ijodimda markaziy o'rin tutadi va u aynan shu bolalikdan boshlangan.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$1963-yilda Toshkent davlat universitetining jurnalistika fakultetini tugatganman.

Talabalik yillarim adabiy muhitga kirishimga yordam bergan: universitetda she'riyat kechalari o'tkazilar, yosh ijodkorlar to'planardi. Ilk she'rlarim aynan shu davrda matbuotda bosilgan. Jurnalistika ta'limi menga aniq va tushunarli yozishni o'rgatgan — bu she'riyatda ham asqotadi.$$
 WHERE topic_uz = $$O'qishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$1992-yilda O'zbekiston Respublikasi Davlat madhiyasi matnini yozganman.

Madhiya matni yozish alohida mas'uliyat: u qisqa bo'lishi, yodlanishi oson bo'lishi va butun xalq nomidan gapirishi kerak. Unda vatan, mustaqillik va kelajakka ishonch mavzulari jamlangan. Matn musiqaga solinishi ham hisobga olinadi — har bo'g'in ohangga tushishi lozim. Madhiya davlat ramzlaridan biri va u rasmiy tadbirlarda ijro etiladi.$$
 WHERE topic_uz = $$Davlat madhiyasi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$She'riy kitoblarim orasida «Mitti yulduz», «Ko'zlarim yo'lingda» va «Onajon» bor.

