 WHERE topic_uz = $$She'riy kitoblarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$«Jannatga yo'l» va «Sohibqiron» dostonlarini yozganman.

