 WHERE topic_uz = $$Sahna asarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$Dantening «Ilohiy komediya» asarini hamda Pushkin, Nekrasov, Shevchenko she'rlarini o'zbekchaga o'girganman.

«Ilohiy komediya» — jahon adabiyotining eng murakkab asarlaridan biri: u she'riy shaklda, uch qismdan iborat va falsafiy mazmunga ega. Uni tarjima qilish yillar davom etgan. Bunday ishlar o'zbek tilining imkoniyatlarini kengaytiradi: chet el asaridagi murakkab fikrni berish uchun yangi ifodalar izlashga to'g'ri keladi.$$
 WHERE topic_uz = $$Tarjimalarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$1990-yilda O'zbekiston xalq shoiri, 1998-yilda esa O'zbekiston Qahramoni unvoniga sazovor bo'lganman.

«O'zbekiston Qahramoni» — mamlakatdagi eng yuksak unvon. Bu e'tiroflar adabiyotdagi va jamoat ishidagi faoliyatim uchun berilgan. Ammo shoir uchun eng katta baho boshqa: she'rining yodlanishi va odamlar dilida yashashi. Mening ko'p she'rlarim maktabda o'qitiladi va qo'shiq bo'lib kuylanadi.$$
 WHERE topic_uz = $$Unvonlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$1983-yilda Hamza, 1992-yilda esa Alisher Navoiy nomidagi Davlat mukofotlarini olganman.

Navoiy nomidagi mukofot adabiyot va san'at sohasidagi eng nufuzli mukofotlardan biri. U yaratilgan asar uchun beriladi, ya'ni bu aniq ishning bahosi. Mukofotlar shoir uchun muhim, ammo ular ijodning maqsadi emas — maqsad o'quvchiga yetib borish va uni o'ylantirish.$$
 WHERE topic_uz = $$Mukofotlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

