 WHERE topic_uz = $$Madhiya musiqasi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'abdulla-oripov');

UPDATE fact_cards SET detail_uz = $$She'rlarim dunyoning ko'plab tillariga tarjima qilingan.

