 WHERE topic_uz = $$To'maris haqida$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'halima-xudoyberdiyeva');

UPDATE fact_cards SET detail_uz = $$1990-yilda Hamza nomidagi davlat mukofotini, 1992-yilda esa «O'zbekiston xalq shoirasi» unvonini olganman.

