 WHERE topic_uz = $$«El-yurt hurmati»$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'halima-xudoyberdiyeva');

UPDATE fact_cards SET detail_uz = $$Sirdaryo viloyatida mening nomimdagi ijod maktabi ochilgan.

