 WHERE topic_uz = $$Nomimdagi maktab$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'halima-xudoyberdiyeva');

UPDATE fact_cards SET detail_uz = $$«Oq olmalar» va «Suyanch tog'larim» kabi she'riy to'plamlarim nashr etilgan.

