 WHERE topic_uz = $$«Alkimyogar» tarjimam$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'ozod-sharafiddinov');

UPDATE fact_cards SET detail_uz = $$Umrimning oxirida og'ir kasallikka chalindim, lekin ijodni to'xtatmadim.

